import json
# Get pages around page 9-11 for 2016 document
data = json.load(open('/app/resources/treasury_bulletin_2016_03.json'))
for elem in data['document']['elements']:
    if elem.get('type') == 'text':
        bbox = elem.get('bbox', [])
        if bbox:
            page_id = bbox[0].get('page_id')
            if page_id and 9 <= page_id <= 12:
                content = elem.get('content', '')
                # Look for actual numbers in table-like format
                if '[' in content and ']' in content and '%' in content:
                    print(f'Page {page_id}: {content}')
